void ipm_remap(const uint8 *src, uint8 *bird)
{
    for(int y = 0; y < IPM_BIRD_H; y++)
    {
        for(int x = 0; x < IPM_BIRD_W; x++)
        {
            int16 sx = invx[y][x];
            int16 sy = invy[y][x];
            if(sx >= 0 && sy >= 0)
            {
                bird[y * IPM_BIRD_W + x] = src[sy * IPM_SRC_W + sx];
            }
            else
            {
                bird[y * IPM_BIRD_W + x] = 0;
            }
        }
    }
}


// 正向映射：把原图坐标 (sx,sy) 映射到鸟瞰坐标（TC264 mapx/mapy 同向）。
// 供迷宫法在原图找完边线后，把边线点转到鸟瞰坐标系。越界返回 -1。
void ipm_map_point(int16 sx, int16 sy, int16 *bx, int16 *by)
{
    if(sx < 0 || sx >= IPM_SRC_W || sy < 0 || sy >= IPM_SRC_H)
    {
        *bx = -1; *by = -1; return;
    }
    *bx = mapx[sy][sx];
    *by = mapy[sy][sx];
}
